{"probes": [{"obligation_id": "OB-005", "strategy": "metamorphic", "rationale": "The clause requires allocate(-t, weights) to equal the elementwise negation of allocate(t, weights) for any integer t and accepted weights; largest-remainder-style allocators commonly break this symmetry (e.g. via floor division or clamping negative amounts to zero), so searching over t and weights should surface a counterexample.", "code": "import pytest
from hypothesis import given, strategies as st, settings

weights_strategy = st.lists(st.integers(min_value=1, max_value=1000), min_size=1, max_size=8)
t_strategy = st.integers(min_value=-100000, max_value=100000)

@given(t=t_strategy, weights=weights_strategy)
@settings(max_examples=100)
def test_allocate_negation_symmetry(t, weights):
    try:
        pos = impl.allocate(t, weights)
        neg = impl.allocate(-t, weights)
    except ValueError:
        return
    assert neg == [-x for x in pos], (
        f"allocate(-{t}, {weights}) = {neg} != negation of allocate({t}, {weights}) = {[-x for x in pos]}"
    )

import impl
